/**
 * Pod Explainer Generator
 *
 * Generates the Stage-1 "explainer" payload for each listening pod sentence:
 *   - explainer_decomposition: ordered chunk-pairs [{chunk_target, chunk_known}, ...]
 *   - explainer_text:         narration string for xAI multilingual TTS
 *
 * Stage-1 sequence per sentence (player-side):
 *     target → known → explainer → target → target
 *
 * Stage-1 only. Subsequent stages skip the explainer slot. Audio is
 * generated by a downstream pass once explainer_text is populated.
 *
 * Architecture:
 *   - Decomposition + narration are produced by Haiku (via the existing
 *     claude-cli.cjs helper — Max Plan, not the API). Per-sentence call.
 *   - Connector word ("means", "significa", "veut dire", ...) localises
 *     from the course's `_for_<lang>` half.
 *   - Writes are routed through Supabase service-role client; the caller
 *     (admin endpoint) is responsible for auth + batching.
 *
 * Skipped courses (config-side, baked into one place so they can't drift):
 *   - cym, cym_n, cym_s — Welsh has TTS voice quality blocker.
 *   - hrv_for_eng — pod-0 still atomised; explainers would target the
 *     atomised rows and be wasted work when the merge-and-regen happens.
 */

const { claudeChat } = require('./shared/claude-cli.cjs')

// =============================================================================
// CONNECTOR LOCALISATION
// =============================================================================
//
// The connector phrase joins chunk-target with chunk-known in the narration.
// Example narration for Italian-for-English: "buona means good, sera means
// afternoon, come stai means how are you doing".
//
// Localised per learner language (the second half of course_code: e.g.
// `ita_for_eng` → "eng" → "means"). Falls back to "means" for unknown.
// We could let Haiku pick it, but pinning it here keeps the narration
// consistent across the catalogue and removes a class of LLM variance.

const CONNECTOR_BY_LEARNER_LANG = {
  eng: 'means',
  spa: 'significa',
  fra: 'veut dire',
  ita: 'significa',
  por: 'significa',
  deu: 'bedeutet',
  nld: 'betekent',
  jpn: 'は ... という意味です', // handled differently in prompt (postfix construction)
  zho: '意思是',
  kor: '의 뜻은',
  ara: 'يعني',
  tur: 'demek',
  pol: 'oznacza',
  rus: 'означает',
}

function getConnectorForLearnerLang(learnerLang) {
  return CONNECTOR_BY_LEARNER_LANG[learnerLang] || 'means'
}

function parseCourseCode(courseCode) {
  // "ita_for_eng" → { target: "ita", learner: "eng" }
  // "fra_ca_for_eng" → { target: "fra_ca", learner: "eng" }
  // "eng_for_jpn" → { target: "eng", learner: "jpn" }
  const m = String(courseCode).match(/^(.+)_for_(.+)$/)
  if (!m) return { target: courseCode, learner: 'eng' }
  return { target: m[1], learner: m[2] }
}

// =============================================================================
// SKIP RULES
// =============================================================================

const SKIPPED_TARGET_LANGS = new Set(['cym', 'cym_n', 'cym_s'])

function shouldSkipCourse(courseCode) {
  const { target } = parseCourseCode(courseCode)
  if (SKIPPED_TARGET_LANGS.has(target)) return { skip: true, reason: 'welsh-tts-blocker' }
  if (courseCode === 'hrv_for_eng') return { skip: true, reason: 'pod-0-atomised-pending-redo' }
  return { skip: false }
}

// =============================================================================
// PROMPT BUILDING
// =============================================================================

/**
 * Build the Haiku prompt to produce decomposition + narration for a BATCH
 * of sentences. The CLI startup cost is ~2-15s per invocation regardless
 * of payload size, so we amortise it by handling many sentences per call.
 *
 * Returns a prompt that asks the model to emit a strict JSON array, one
 * entry per input sentence, in the same order:
 *   [
 *     { "id": "<echo>", "decomposition": [...], "explainer_text": "..." },
 *     ...
 *   ]
 *
 * Chunks are LEGO-sized — meaningful semantic units, NOT one word per
 * chunk (compound concepts like "come stai" stay together). Keeps the
 * methodology consistent with the course-side phrase decomposition.
 */
function buildBatchPrompt({ sentences, targetLang, learnerLang, connector }) {
  const inputBlock = sentences
    .map((s, i) => `${i + 1}. id=${JSON.stringify(s.id)}  target=${JSON.stringify(s.target_text)}  known=${JSON.stringify(s.known_text)}`)
    .join('\n')
  return `You are decomposing sentences for a language-learning app.
Target language: ${targetLang}
Learner language: ${learnerLang}

For EACH sentence below, produce two things:

1. "decomposition": ordered array of LEGO-sized chunk-pairs walking through
   the target sentence left-to-right. Each chunk-pair has the target fragment
   and its known-language meaning. Chunks are meaningful semantic units
   (e.g. "come stai" stays together as one chunk meaning "how are you doing"),
   NOT one-word-per-chunk.

2. "explainer_text": a single narration string for TTS that says each chunk
   in the target language, connected with the connector phrase "${connector}",
   with the known meaning. Use natural punctuation.

USE JUDGMENT — an explainer is only useful when the sentence has TWO OR
MORE meaningful chunks to decompose. The Stage-1 explainer earns its
keep by helping the learner see "this longer target breaks down into
these reusable pieces". If the target sentence consists of only ONE
meaningful chunk (after dropping any proper nouns), the explainer
adds nothing — the target/known pair already conveys the same one
mapping. Return an empty decomposition and empty explainer_text in
that case.

Specifically:
- PROPER NOUNS — names of people, places, brands — are NOT translated
  and are NOT explained. Drop them entirely from the decomposition.
  "Giulia means Giulia" is noise.
- After dropping proper nouns, if only ONE meaningful chunk remains
  (e.g. "Buongiorno, Anna!" → only "buongiorno" is left), skip the
  explainer for this sentence. Return empty decomposition + empty
  explainer_text. The player gracefully shows no Stage-1 slot.
- If the sentence is purely a proper noun ("Sarah!"), also empty.
- If TWO OR MORE meaningful chunks remain, produce the full
  decomposition + narration as described above.

EXAMPLE 1 — multi-chunk, no proper nouns (explainer earns its keep):
   Input target: "Buona sera, come stai?"
   Input known:  "Good afternoon, how are you doing?"
   Output entry:
   {
     "id": "<echo the input id>",
     "decomposition": [
       { "chunk_target": "buona", "chunk_known": "good" },
       { "chunk_target": "sera", "chunk_known": "afternoon" },
       { "chunk_target": "come stai", "chunk_known": "how are you doing" }
     ],
     "explainer_text": "buona means good, sera means afternoon, come stai means how are you doing"
   }

EXAMPLE 2 — single chunk after dropping name (no explainer needed):
   Input target: "Buongiorno, Giulia!"
   Input known:  "Good morning, Giulia!"
   Output entry:
   {
     "id": "<echo the input id>",
     "decomposition": [],
     "explainer_text": ""
   }

EXAMPLE 3 — purely a name (no explainer):
   Input target: "Anna!"
   Input known:  "Anna!"
   Output entry:
   {
     "id": "<echo the input id>",
     "decomposition": [],
     "explainer_text": ""
   }

INPUT (one sentence per line):
${inputBlock}

OUTPUT FORMAT: a JSON array, one object per input sentence in the same
order, each with "id" (echoed), "decomposition", "explainer_text". Output
ONLY the JSON array. No prose, no markdown, no code fences.`
}

/**
 * Parse the model's batch response into a Map of id → result. Tolerant of
 * accidental code fences. Skips entries that are structurally broken — the
 * caller treats those as failures and surfaces them per-row.
 */
function parseBatchResponse(raw) {
  if (!raw || typeof raw !== 'string') {
    throw new Error('Empty model response')
  }
  const m = raw.match(/\[[\s\S]*\]/)
  if (!m) throw new Error('No JSON array found in model response')
  let parsed
  try {
    parsed = JSON.parse(m[0])
  } catch (e) {
    throw new Error(`Invalid JSON array from model: ${e.message}`)
  }
  if (!Array.isArray(parsed)) {
    throw new Error('Model response is not an array')
  }
  const byId = new Map()
  for (const entry of parsed) {
    if (!entry || typeof entry.id !== 'string') continue
    if (!Array.isArray(entry.decomposition)) continue
    if (typeof entry.explainer_text !== 'string') continue
    let bad = false
    for (const e of entry.decomposition) {
      if (
        !e ||
        typeof e.chunk_target !== 'string' ||
        typeof e.chunk_known !== 'string'
      ) {
        bad = true
        break
      }
    }
    if (bad) continue
    // Empty decomposition + empty explainer_text is a valid result for
    // sentences that consist entirely of proper nouns (names, places).
    // Stage-1 player skips the slot when explainer_audio_id is NULL, so
    // an empty text means "no explainer needed for this sentence".
    byId.set(entry.id, {
      decomposition: entry.decomposition.map(e => ({
        chunk_target: e.chunk_target,
        chunk_known: e.chunk_known,
      })),
      explainer_text: entry.explainer_text.trim(),
    })
  }
  return byId
}

// =============================================================================
// PUBLIC API
// =============================================================================

/**
 * Generate explainer payload for a BATCH of sentences from the same course.
 * One CLI invocation handles up to ~15 sentences — the CLI startup cost
 * (~2-15s) is dominated by spawning the subprocess, not by the model work
 * itself, so amortising across many sentences is a ~10× speedup over
 * per-sentence calls.
 *
 * Returns a Map<id, { decomposition, explainer_text }>. The caller treats
 * any input id missing from the returned map as a per-row failure (rather
 * than failing the whole batch) so a single garbled JSON entry doesn't
 * stall an entire pod.
 *
 * Throws only on hard CLI failures or completely unparseable output.
 */
async function generateForBatch({ courseCode, sentences }) {
  if (!Array.isArray(sentences) || sentences.length === 0) return new Map()
  const { target, learner } = parseCourseCode(courseCode)
  const connector = getConnectorForLearnerLang(learner)
  const prompt = buildBatchPrompt({
    sentences,
    targetLang: target,
    learnerLang: learner,
    connector,
  })
  const raw = await claudeChat(prompt, { model: 'haiku' })
  return parseBatchResponse(raw)
}

module.exports = {
  generateForBatch,
  parseCourseCode,
  getConnectorForLearnerLang,
  shouldSkipCourse,
  // Exported for unit testing without needing the CLI.
  _internal: { buildBatchPrompt, parseBatchResponse },
}
